export function TeamSection({
  heading = "{{heading}}",
  columns = "{{columns}}",
  accent = "{{accent}}",
  showRole = {{showRole}},
}) {
  const members = [
    { initials: "MK", name: "Maya Kessler", role: "Co-founder" },
    { initials: "DP", name: "Diego Pardo", role: "Head of Design" },
    { initials: "RJ", name: "Rhea Joshi", role: "Engineering" },
    { initials: "TL", name: "Theo Lang", role: "Customer Success" },
  ].slice(0, Number(columns));
  return (
    <section style={{ font: "15px system-ui, sans-serif", color: "#241430", padding: 24 }}>
      <h2 style={{ margin: "0 0 18px", fontSize: 22, fontWeight: 700 }}>{heading}</h2>
      <div style={{ display: "grid", gap: 20, gridTemplateColumns: `repeat(${columns}, 1fr)` }}>
        {members.map((m) => (
          <div key={m.initials} style={{ textAlign: "center" }}>
            <span style={{ display: "inline-flex", alignItems: "center", justifyContent: "center", width: 64, height: 64,
              borderRadius: "50%", fontWeight: 700, marginBottom: 10, color: "#241430", background: accent }}>{m.initials}</span>
            <p style={{ margin: 0, fontWeight: 700, fontSize: 14 }}>{m.name}</p>
            {showRole && <p style={{ margin: "2px 0 0", fontSize: 12, color: "#241430aa" }}>{m.role}</p>}
          </div>
        ))}
      </div>
    </section>
  );
}
